.logo-light {
  display: none;
}

body.light-mode .logo-dark {
  display: none;
}

body.light-mode .logo-light {
  display: block;
}

.logo-dark img,
.logo-light img {
  position: relative;
  overflow: hidden;
  transition: transform 0.3s ease;
}

.logo-dark img:hover,
.logo-light img:hover {
  transform: scale(1.03);
}

/* Brillo dorado */
.logo-dark img::after,
.logo-light img::after {
  content: "";
  position: absolute;
  top: 0;
  left: -75%;
  width: 50%;
  height: 100%;
  background: linear-gradient(
    120deg,
    rgba(255,255,255,0.0) 0%,
    rgba(255,255,255,0.25) 50%,
    rgba(255,255,255,0.0) 100%
  );
  transform: skewX(-25deg);
  transition: 0.75s;
}

.logo-dark img:hover::after,
.logo-light img:hover::after {
  left: 125%;
}

/* ===== SISTEMA GLOBAL DE TEXTO CONTROLADO POR VARIABLES ===== */

/* Texto base */
body {
  color: var(--text-primary);
}

/* Todos los textos Elementor */
.elementor,
.elementor * {
  color: inherit !important;
}

/* Encabezados */
h1, h2, h3, h4, h5, h6 {
  color: var(--text-primary) !important;
}

/* Párrafos */
p {
  color: var(--text-primary) !important;
}

/* Texto secundario opcional */
.text-muted {
  color: var(--text-secondary) !important;
}

/* Links */
a {
  color: var(--gold-primary) !important;
}

a:hover {
  color: var(--gold-hover) !important;
}

