#baHeaderMenuRoot {
  display: flex;
  justify-content: flex-end;
  align-items: center;
}

.ba5-user-menu {
  position: relative;
  display: inline-block;
}

.ba5-user-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 10px 16px;
  border-radius: 12px;
  border: 1px solid rgba(182, 140, 42, 0.55);
  background: linear-gradient(90deg, #b68c2a, #d4af37);
  color: #fff !important;
  font-weight: 700;
  font-size: 15px;
  text-decoration: none !important;
  cursor: pointer;
  transition: filter .2s ease, transform .15s ease;
}

.ba5-user-btn:hover {
  filter: brightness(1.05);
  transform: translateY(-1px);
}

.ba5-user-btn-menu::after {
  content: "▾";
  margin-left: 8px;
  font-size: 12px;
}

.ba5-user-dropdown {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  width: 300px;
  padding: 10px;
  border-radius: 14px;
  border: 1px solid rgba(182, 140, 42, 0.35);
  background: #0f1622;
  box-shadow: 0 14px 30px rgba(0, 0, 0, 0.35);
  display: none;
  z-index: 99999;
}

.ba5-user-menu.is-open .ba5-user-dropdown {
  display: block;
}

.ba5-user-head {
  padding: 10px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  margin-bottom: 8px;
}

.ba5-user-name {
  color: #fff;
  font-weight: 700;
  font-size: 14px;
}

.ba5-user-email {
  color: #bfc9d8;
  font-size: 12px;
  margin-top: 2px;
  word-break: break-all;
}

.ba5-plan-box {
  margin: 6px 0 10px;
  padding: 10px;
  border-radius: 10px;
  background: rgba(212, 175, 55, 0.12);
  border: 1px solid rgba(212, 175, 55, 0.35);
}

.ba5-plan-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
}

.ba5-plan-label {
  color: #d8c27a;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: .5px;
}

.ba5-plan-pill {
  font-size: 11px;
  font-weight: 700;
  border-radius: 999px;
  padding: 3px 8px;
  border: 1px solid transparent;
}

.ba5-plan-pill.is-active {
  color: #b7ffd1;
  background: rgba(24, 143, 72, 0.25);
  border-color: rgba(113, 255, 173, 0.4);
}

.ba5-plan-pill.is-pending {
  color: #ffe0a6;
  background: rgba(173, 114, 13, 0.25);
  border-color: rgba(255, 209, 126, 0.4);
}

.ba5-plan-name {
  color: #fff;
  font-size: 14px;
  font-weight: 700;
  margin-top: 6px;
}

.ba5-plan-renewal {
  color: #cfd7e4;
  font-size: 12px;
  margin-top: 3px;
}

.ba5-user-item {
  display: block;
  width: 100%;
  text-align: left;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: #fff !important;
  text-decoration: none !important;
  padding: 10px;
  font-size: 14px;
  cursor: pointer;
}

.ba5-user-item:hover {
  background: rgba(255, 255, 255, 0.08);
}

.ba5-user-logout {
  color: #ffd9d9 !important;
}

body.light-mode .ba5-user-btn {
  color: #fff !important;
}

